begin;select plan(8);select has_table('public','apostolic_research_catalog');select has_table('public','apostolic_city_research');select has_table('public','apostolic_research_queue');select is((select count(*)::integer from public.apostolic_research_catalog),8,'eight researches');select is((select count(*)::integer from public.apostolic_research_catalog where base_costs?'gems'),0,'no gems');select function_returns('public','apostolic_start_research',array['text','uuid'],'jsonb');select function_returns('public','apostolic_finish_research',array[]::text[],'jsonb');select function_returns('public','apostolic_get_research_center',array[]::text[],'jsonb');select*from finish();rollback;
